BEGIN READ ONLY;
SELECT json_build_object('read_at',clock_timestamp(), 'migrations',(SELECT json_agg(json_build_object('name',migration_name,'checksum',checksum,'finished',finished_at IS NOT NULL,'rolled_back',rolled_back_at IS NOT NULL) ORDER BY migration_name) FROM _prisma_migrations), 'new_migration_ms',(SELECT extract(epoch FROM finished_at-started_at)*1000 FROM _prisma_migrations WHERE migration_name='20261009150000_site_setting_site_search_enabled'), 'business_tables',(SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' AND table_name<>'_prisma_migrations'), 'search_column_exists', EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='site_setting' AND column_name='site_search_enabled'), 'search_values',(SELECT json_agg(site_search_enabled) FROM site_setting), 'web_update',has_column_privilege('web_app','site_setting','site_search_enabled','UPDATE'), 'scheduler_select',has_column_privilege('scheduler_app','site_setting','site_search_enabled','SELECT'));
COMMIT;
